import re


def eval_expression(expr: str) -> float:
    """
    Evaluate a mathematical expression string supporting +, -, *, /, parentheses,
    and negative numbers. Follows standard order of operations.
    Raises ZeroDivisionError when dividing by zero.
    """
    # Tokenize the expression
    tokens = tokenize(expr)
    # Use a recursive descent parser
    pos = 0

    def current_token():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume_token(token_type=None):
        nonlocal pos
        tok = current_token()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if token_type is not None and tok[0] != token_type:
            raise ValueError(f"Expected {token_type}, got {tok}")
        pos += 1
        return tok

    def parse_expression():
        """Handle addition and subtraction (lowest precedence)."""
        node = parse_term()
        while True:
            tok = current_token()
            if tok is None:
                break
            if tok[0] == '+':
                pos += 1
                right = parse_term()
                node = ('+', node, right)
            elif tok[0] == '-':
                pos += 1
                right = parse_term()
                node = ('-', node, right)
            else:
                break
        return node

    def parse_term():
        """Handle multiplication and division."""
        node = parse_factor()
        while True:
            tok = current_token()
            if tok is None:
                break
            if tok[0] == '*':
                pos += 1
                right = parse_factor()
                node = ('*', node, right)
            elif tok[0] == '/':
                pos += 1
                right = parse_factor()
                node = ('/', node, right)
            else:
                break
        return node

    def parse_factor():
        """Handle unary minus and atoms (numbers, parenthesized expressions)."""
        tok = current_token()
        if tok is None:
            raise ValueError("Unexpected end of expression")

        # Unary minus
        if tok[0] == '-':
            pos += 1
            operand = parse_factor()
            return ('neg', operand)
        elif tok[0] == '+':
            pos += 1
            return parse_factor()

        return parse_atom()

    def parse_atom():
        """Handle numbers and parenthesized expressions."""
        tok = current_token()
        if tok is None:
            raise ValueError("Unexpected end of expression")

        if tok[0] == '(':
            consume_token('(')
            node = parse_expression()
            consume_token(')')
            return node
        elif tok[0] == 'NUMBER':
            pos += 1
            return ('num', tok[1])
        else:
            raise ValueError(f"Unexpected token: {tok}")

    def evaluate(node):
        """Evaluate the parse tree."""
        if node[0] == 'num':
            return float(node[1])
        elif node[0] == 'neg':
            return -evaluate(node[1])
        elif node[0] == '+':
            return evaluate(node[1]) + evaluate(node[2])
        elif node[0] == '-':
            return evaluate(node[1]) - evaluate(node[2])
        elif node[0] == '*':
            return evaluate(node[1]) * evaluate(node[2])
        elif node[0] == '/':
            left = evaluate(node[1])
            right = evaluate(node[2])
            if right == 0:
                raise ZeroDivisionError("division by zero")
            return left / right
        else:
            raise ValueError(f"Unknown node: {node}")

    # Parse and evaluate
    result_node = parse_expression()
    # Ensure all tokens are consumed
    if pos != len(tokens):
        raise ValueError(f"Unexpected token at position {pos}: {tokens[pos]}")

    result = evaluate(result_node)
    # Return int if result is a whole number, else float
    if result == int(result):
        return int(result)
    return result


def tokenize(expr: str):
    """Tokenize the expression into a list of (type, value) tuples."""
    expr = expr.replace(' ', '')
    tokens = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch in '+-*/()':
            tokens.append((ch, ch))
            i += 1
        elif ch.isdigit() or ch == '.':
            # Parse number (integer or float)
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            num_str = expr[i:j]
            tokens.append(('NUMBER', num_str))
            i = j
        else:
            raise ValueError(f"Unexpected character: {ch}")
    return tokens
